repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 3), ('lodge', 35), ('lodge', 47), ('lodge', 20), ('grand', 29), ('plaza', 28), ('plaza', 38)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.positions.py:
"""Position windows over bookings."""


def nights_between(bookings, low, high):
    """Return the nights of the bookings at positions low to high, both included. Positions start at 1."""
    return [x.nights for x in bookings[low - 1:high - 1]]


def first_nightss(bookings, n):
    """Return the nights of the first n bookings."""
    return nights_between(bookings, 1, n)


def hotel_names(bookings):
    """Return the distinct hotel values, in first-seen order."""
    names = []
    for x in bookings:
        if x.hotel not in names:
            names.append(x.hotel)
    return names
